48	macro_rules! os_services {
49	    () => {
50	        fn getenv(&mut self, name: &str) -> Option<String> {
51	            std::env::var(name).ok()
52	        }
53	        fn setenv(&mut self, name: &str, value: &str) {
54	            std::env::set_var(name, value);
55	        }
56	        fn now(&mut self) -> Option<(u64, u32)> {
