1	//! `reva` — command-line host for the portable Reva core.
2	//!
3	//! ```text
4	//! reva [options] [file ...]
5	//! ```
6	//!
7	//! Boots `reva.f` (embedded), includes each file, evaluates each `-e` text,
8	//! then reads standard input: line by line with a prompt on a terminal, or
9	//! to end of input otherwise (so `reva x.f < /dev/null` is a batch run).
10	//! The exit status is the `bye` code (0 at end of input).
11	//!
12	//! `restart` starts over the way this run started (boot or `--image`),
13	//! includes the files and evaluates the `-e` texts again, then goes on
14	//! reading the input that is left.
15	
16	use std::io::{self, BufRead, IsTerminal, Read, Write};
17	use std::process::ExitCode;
18	use std::time::{Duration, SystemTime, UNIX_EPOCH};
19	
20	use reva_vm::vfs::FileSystem;
21	use reva_vm::{embedded, Host, Machine, Start, Status};
22	
23	const USAGE: &str = "\
24	usage: reva [options] [file ...]
25	
26	  -e, --eval TEXT      evaluate TEXT after the files (repeatable)
27	      --boot PATH      boot from PATH instead of the embedded reva.f
28	      --no-boot        start from the bare core (no reva.f at all)
29	      --image PATH     start from a saved image instead of booting
30	      --save-image PATH  after files and -e, save an image and exit
31	      --show-boot      print what booting printed (progress digits, errors)
32	      --trace          trace every VM step to stderr (very slow)
33	  -h, --help           this text
34	  -V, --version        version
35	";
36	
37	mod fs;
38	
39	struct StdHost {
40	    out: io::BufWriter<io::Stdout>,
41	    fs: fs::StdFs,
42	    /// While booting: output is collected here so the progress digits
43	    /// stay quiet.
44	    capture: Option<Vec<u8>>,
45	}
46	
47	/// Process environment, clock and file system, shared by both hosts.
48	macro_rules! os_services {
49	    () => {
50	        fn getenv(&mut self, name: &str) -> Option<String> {
51	            std::env::var(name).ok()
52	        }
53	        fn setenv(&mut self, name: &str, value: &str) {
54	            std::env::set_var(name, value);
55	        }
56	        fn now(&mut self) -> Option<(u64, u32)> {
57	            let d = SystemTime::now().duration_since(UNIX_EPOCH).ok()?;
58	            Some((d.as_secs(), d.subsec_micros()))
59	        }
60	        fn sleep_ms(&mut self, ms: u32) {
61	            std::thread::sleep(Duration::from_millis(ms.into()));
62	        }
63	        fn fs(&mut self) -> Option<&mut dyn FileSystem> {
64	            Some(&mut self.fs)
65	        }
66	    };
67	}
68	
69	impl Host for StdHost {
70	    fn write(&mut self, bytes: &[u8]) {
71	        match &mut self.capture {
72	            Some(c) => c.extend_from_slice(bytes),
73	            None => {
74	                let _ = self.out.write_all(bytes);
75	            }
76	        }
77	    }
78	
79	    os_services!();
80	
81	    fn read_input_blocking(&mut self) -> Option<Vec<u8>> {
82	        if self.capture.is_some() {
83	            return None;
84	        }
85	        let _ = self.out.flush();
86	        let mut line = String::new();
87	        match io::stdin().lock().read_line(&mut line) {
88	            Ok(_) => Some(line.into_bytes()),
89	            Err(_) => None,
90	        }
91	    }
92	}
93	
94	#[derive(Default)]
95	struct Options {
96	    files: Vec<String>,
97	    evals: Vec<String>,
98	    boot: Option<String>,
99	    no_boot: bool,
100	    image: Option<String>,
101	    save_image: Option<String>,
102	    show_boot: bool,
103	    trace: bool,
104	}
105	
106	fn parse_args() -> Result<Options, String> {
107	    let mut o = Options::default();
108	    let mut args = std::env::args().skip(1);
109	    while let Some(a) = args.next() {
110	        let mut value = |name: &str| args.next().ok_or(format!("{name} needs a value"));
111	        match a.as_str() {
112	            "-e" | "--eval" => o.evals.push(value(&a)?),
113	            "--boot" => o.boot = Some(value(&a)?),
114	            "--no-boot" => o.no_boot = true,
115	            "--image" => o.image = Some(value(&a)?),
116	            "--save-image" => o.save_image = Some(value(&a)?),
117	            "--show-boot" => o.show_boot = true,
118	            "--trace" => o.trace = true,
119	            "-h" | "--help" => {
120	                print!("{USAGE}");
121	                std::process::exit(0);
122	            }
123	            "-V" | "--version" => {
124	                println!("reva {} (portable vx86 core)", env!("CARGO_PKG_VERSION"));
125	                std::process::exit(0);
126	            }
127	            s if s.starts_with('-') && s.len() > 1 => return Err(format!("unknown option {s}")),
128	            _ => o.files.push(a),
129	        }
130	    }
131	    Ok(o)
132	}
133	
134	fn exit_code(code: i32) -> ExitCode {
135	    ExitCode::from((code & 0xff) as u8)
136	}
137	
138	fn main() -> ExitCode {
139	    let opts = match parse_args() {
140	        Ok(o) => o,
141	        Err(e) => {
142	            eprintln!("reva: {e}\n{USAGE}");
143	            return ExitCode::from(2);
144	        }
145	    };
146	
147	    let boot_path = opts
148	        .boot
149	        .clone()
150	        .unwrap_or_else(|| embedded::BOOT_PATH.to_string());
151	    let (start, mut vm) = match &opts.image {
152	        Some(path) => {
153	            let loaded = std::fs::read(path)
154	                .map_err(|e| e.to_string())
155	                .and_then(|b| Start::image(b).map_err(|e| e.to_string()));
156	            match loaded {
157	                Ok(sm) => sm,
158	                Err(e) => {
159	                    eprintln!("reva: {path}: {e}");
160	                    return ExitCode::from(2);
161	                }
162	            }
163	        }
164	        None => {
165	            let mut args = vec!["reva".to_string()];
166	            if !opts.no_boot {
167	                args.push(boot_path);
168	            }
169	            let start = Start::Boot(args);
170	            let vm = start
171	                .machine()
172	                .expect("a boot start always makes a machine");
173	            (start, vm)
174	        }
175	    };
176	    let run = Run {
177	        interactive: io::stdin().is_terminal() && opts.save_image.is_none(),
178	        opts: &opts,
179	        start,
180	    };
181	    let mut host = StdHost {
182	        out: io::BufWriter::new(io::stdout()),
183	        fs: fs::StdFs::default(),
184	        capture: None,
185	    };
186	    if let Err(code) = run.begin(&mut vm, &mut host) {
187	        return code;
188	    }
189	    let status = run.until_blocked(&mut vm, &mut host);
190	    let _ = host.out.flush();
191	    match status {
192	        Ok(Status::Halted(code)) => return exit_code(code),
193	        Err(code) => return code,
194	        Ok(_) => {}
195	    }
196	
197	    if let Some(path) = &opts.save_image {
198	        if let Err(e) = std::fs::write(path, vm.save_image()) {
199	            eprintln!("reva: {path}: {e}");
200	            return ExitCode::from(2);
201	        }
202	        return ExitCode::SUCCESS;
203	    }
204	
205	    let stdin = io::stdin();
206	    if !stdin.is_terminal() {
207	        let mut all = Vec::new();
208	        if let Err(e) = stdin.lock().read_to_end(&mut all) {
209	            eprintln!("reva: stdin: {e}");
210	        }
211	        vm.feed(&all);
212	        vm.close_input();
213	        let status = run.until_blocked(&mut vm, &mut host);
214	        let _ = host.out.flush();
215	        return match status {
216	            Ok(Status::Halted(code)) => exit_code(code),
217	            Err(code) => code,
218	            Ok(_) => ExitCode::SUCCESS,
219	        };
220	    }
221	
222	    // Interactive: one line at a time; reva.f prints the prompt.
223	    loop {
224	        let _ = host.out.flush();
225	        let mut line = String::new();
226	        match stdin.lock().read_line(&mut line) {
227	            Ok(0) | Err(_) => vm.close_input(),
228	            Ok(_) => vm.feed(line.as_bytes()),
229	        }
230	        let status = run.until_blocked(&mut vm, &mut host);
231	        let _ = host.out.flush();
232	        match status {
233	            Ok(Status::Halted(code)) => return exit_code(code),
234	            Err(code) => return code,
235	            Ok(_) => {}
236	        }
237	    }
238	}
239	
240	/// How this run starts, kept for `restart`.
241	struct Run<'a> {
242	    opts: &'a Options,
243	    start: Start,
244	    interactive: bool,
245	}
246	
247	impl Run<'_> {
248	    /// Start `vm`: boot quietly (reva.f prints progress marks, then, as the
249	    /// restarted system, its banner and first prompt; anything else means
250	    /// the boot went wrong, so show it), then queue the files and `-e`
251	    /// texts.
252	    fn begin(&self, vm: &mut Machine, host: &mut StdHost) -> Result<(), ExitCode> {
253	        let opts = self.opts;
254	        host.capture = Some(Vec::new());
255	        let status = vm.run_until_blocked(host);
256	        let boot_out = host.capture.take().unwrap_or_default();
257	        match status {
258	            Status::Halted(code) => {
259	                io::stdout().write_all(&boot_out).ok();
260	                eprintln!("reva: halted during boot");
261	                return Err(exit_code(code));
262	            }
263	            Status::Restart => {
264	                io::stdout().write_all(&boot_out).ok();
265	                eprintln!("reva: restart during boot");
266	                return Err(ExitCode::from(2));
267	            }
268	            _ => {}
269	        }
270	        let boot_out = String::from_utf8_lossy(&boot_out).into_owned();
271	        let (marks, rest) = embedded::split_boot_output(&boot_out);
272	        let normal = !rest.contains("***") && (rest.is_empty() || rest.starts_with("Reva "));
273	        if opts.show_boot || !normal {
274	            eprint!("{marks}{rest}");
275	            if !boot_out.ends_with('\n') && !boot_out.is_empty() {
276	                eprintln!();
277	            }
278	        }
279	        if self.interactive {
280	            // The banner and first `ok>` prompt, as Reva showed them.
281	            if normal && !opts.show_boot {
282	                let _ = host.out.write_all(rest.as_bytes());
283	            }
284	        } else {
285	            vm.quiet_prompt();
286	        }
287	        vm.set_trace(opts.trace);
288	
289	        let mut pending = Vec::new();
290	        for f in &opts.files {
291	            pending.extend_from_slice(format!("include {f}\n").as_bytes());
292	        }
293	        for e in &opts.evals {
294	            pending.extend_from_slice(e.as_bytes());
295	            pending.push(b'\n');
296	        }
297	        vm.feed(&pending);
298	        Ok(())
299	    }
300	
301	    /// Run until `vm` needs input or halts; on `restart`, start a new
302	    /// machine the same way and hand it the input not yet read.
303	    fn until_blocked(&self, vm: &mut Machine, host: &mut StdHost) -> Result<Status, ExitCode> {
304	        loop {
305	            match vm.run_until_blocked(host) {
306	                Status::Restart => {
307	                    let (input, closed) = vm.take_input();
308	                    *vm = self.start.machine().map_err(|e| {
309	                        eprintln!("reva: restart: {e}");
310	                        ExitCode::from(2)
311	                    })?;
312	                    self.begin(vm, host)?;
313	                    vm.feed(&input);
314	                    if closed {
315	                        vm.close_input();
316	                    }
317	                }
318	                s => return Ok(s),
319	            }
320	        }
321	    }
322	}
