                Str => {
                    let (a, len) = (cell(i)?, cell(i + 1)?);
                    bytes.push(self.mem.slice(a, len)?.to_vec());
                    i += 1;
                }
            }
            i += 1;
        }
        let _ = EAX;
        Ok(HostCall { service: "sqlite", op, ints, bytes })
    }
