const NEED_INPUT: i32 = 1;
const HALTED: i32 = 2;
const NOT_BOOTED: i32 = -1;
const BAD_IMAGE: i32 = -2;

fn code(s: Status) -> i32 {
    match s {
        Status::Yielded => YIELDED,
        Status::NeedInput => NEED_INPUT,
        Status::Halted(_) => HALTED,
        Status::Restart => YIELDED,
    }
}

