      if (clock) this.setClock();
      const t0 = performance.now();
      let s;
      do s = this.step(budget);
      while (s === YIELDED && performance.now() - t0 < sliceMs);
      const out = this.takeOutput();
      if (out) onOutput(out);
      if (onUi) this.flushUi(onUi);
      if (s !== YIELDED) {
        if (this.storage) this.persist();
        return s;
      }
      await yieldNow();
    }
  }
