38:pub type PathMap = Box<dyn Fn(&str) -> Option<PathBuf> + Send>;
    print_output: bool,
    /// Where graphics go (`--canvas`, else the manifest's `canvas`).
    canvas: Option<String>,
    /// With `--package`: `{ name, title, about, hint }` from the manifest,
    /// for the About dialog and the header.
    package: Option<serde_json::Value>,
    /// Notes for the user (skipped files, a missing manifest, ...).
    notes: Vec<String>,
}

struct State {
    session: Session,
    root: PathBuf,
    brand: Branding,
}

#[derive(Default)]
struct Options {
    package: Option<PathBuf>,
    root: Option<PathBuf>,
    evals: Vec<String>,
    print_output: bool,
    canvas: Option<String>,
}

fn parse_args() -> Result<Options, String> {
            input: o.evals,
            print_output: o.print_output,
            canvas,
            package: package.map(|_| {
                serde_json::json!({
                    "name": manifest.name,
                    "id": manifest.id,
                    "title": manifest.title,
                    "about": manifest.about,
                    "hint": manifest.hint,
                })
            }),
            notes,
        },
        root,
        brand,
    })
}

