        Enc::Utf8 => utf8(b),
        Enc::Latin1 => Ok((char::from(*b.first().ok_or(Bad::Incomplete)?), 1)),
        Enc::Ascii => match b.first() {
            Some(&c) if c < 0x80 => Ok((char::from(c), 1)),
            Some(_) => Err(Bad::Invalid),
            None => Err(Bad::Incomplete),
